import React, { useEffect, useRef, useState } from "react";
import axios from "axios";
import { Html5Qrcode } from "html5-qrcode";
import { useNavigate } from "react-router-dom";

function QRScanner() {
  const [user, setUser] = useState(null);
  const [message, setMessage] = useState("");

  const scannerRef = useRef(null);
  const navigate = useNavigate();

  /* ================================
   CHECK ADMIN LOGIN
================================ */

  useEffect(() => {
    const admin = localStorage.getItem("admin");

    if (!admin) {
      alert("Please login as admin");

      navigate("/admin-login");
    }
  }, [navigate]);

  /* ================================
   START CAMERA SCANNER
================================ */

  useEffect(() => {
    if (scannerRef.current) return;

    const scanner = new Html5Qrcode("reader");

    scannerRef.current = scanner;

    Html5Qrcode.getCameras()
      .then((devices) => {
        if (devices && devices.length) {
          scanner.start(
            devices[0].id,
            {
              fps: 10,
              qrbox: 250,
            },
            (decodedText) => {
              console.log("QR RESULT:", decodedText);

              verifyUser(decodedText);
            },
            (error) => {
              // ignore scan errors
            },
          );
        }
      })
      .catch((err) => {
        console.log("Camera Error:", err);
      });

    return () => {
      if (scannerRef.current) {
        scannerRef.current.stop().catch(() => {});
      }
    };
  }, []);

  /* ================================
   VERIFY USER
================================ */

  const verifyUser = async (id) => {
    try {
      const res = await axios.get(`http://localhost:5000/verify-user/${id}`);

      if (res.data.success) {
        setUser(res.data.user);

        setMessage("✅ VERIFIED - Attendance Marked");

        await axios.put(`http://localhost:5000/mark-attendance/${id}`);
      } else {
        setUser(null);

        setMessage("❌ NOT REGISTERED");
      }
    } catch (err) {
      console.log(err);

      setMessage("⚠️ SERVER ERROR");
    }
  };

  /* ================================
   UI
================================ */

  return (
    <div style={{ padding: "20px" }}>
      <h2>Admin QR Scanner</h2>

      <div id="reader" style={{ width: "320px" }}></div>

      <h3>{message}</h3>

      {user && (
        <div
          style={{
            border: "1px solid #ccc",
            padding: "10px",
            marginTop: "10px",
          }}
        >
          <p>
            <b>Name:</b> {user.name}
          </p>

          <p>
            <b>College:</b> {user.college_name}
          </p>

          <p>
            <b>Phone:</b> {user.phone}
          </p>

          <p>
            <b>Event ID:</b> {user.event_id}
          </p>

          <p style={{ color: "green" }}>Attendance Marked</p>
        </div>
      )}
    </div>
  );
}

export default QRScanner;
